let text = $json.output || "";
//let text = "I can provide information, • Availability Target: 99.95%  Target MTTR: less than 12 minutes" || "";

// Remove bold (**text**)
text = text.replace(/\*\*(.*?)\*\*/g, "$1");

// Remove italic (*text*)
text = text.replace(/\*(.*?)\*/g, "$1");

// Remove inline code
text = text.replace(/`([^`]*)`/g, "$1");

// Remove headings
text = text.replace(/^#+\s*/gm, "");

// Convert markdown bullets
text = text.replace(/^\s*[-*]\s+/gm, "• ");

// Remove links [text](url)
text = text.replace(/\[([^\]]+)\]\(([^)]+)\)/g, "$1");

text = text
  .replace(/&/g, "&amp;")
  .replace(/</g, "&lt;")
  .replace(/>/g, "&gt;");


return [{
  json: {
    text
  }
}];
